options.afterRender:
// The subway as a line diagram laid out by Graphviz in this browser, with
// every train on it. Query N is the network (one row per station of each
// canonical pattern), query T the trains, each on the hop it is running and how
// far along it. The layout is Graphviz's neato in Kamada-Kawai mode, started
// from the stations' real positions and asked for hops of equal length: it
// keeps the shape of the city but opens up downtown, where stations are close,
// and draws the suburbs tighter. The layout depends on the network only, so it
// is computed once per visit; each refresh only moves the trains, which glide
// to their new places.
// Click a station: the map flies to it and the board lists its next trains.
// Click a train: the map follows it. Wheel to zoom, drag to pan, double-click
// to fit.
const VIZ = 'https://cdn.jsdelivr.net/npm/@viz-js/viz@3.30.0/dist/viz.js';
const theme = context.grafana.theme;
const COLOURS = theme.isDark
  ? { Red: '#E8473B', Orange: '#F59A1B', Blue: '#3C7DE0', Green: '#1FA35F', Mattapan: '#E8473B' }
  : { Red: '#DA291C', Orange: '#ED8B00', Blue: '#003DA5', Green: '#00843D', Mattapan: '#DA291C' };
const TEXT = theme.colors.text.primary;
const BACK = theme.colors.background.primary;
const PICK = theme.isDark ? '#FFE14D' : '#B8860B';

const box = context.element.querySelector('.subway-map');
const note = context.element.querySelector('.subway-note');
if (!box) {
  return;
}
context.element.style.height = '100%';

const self = this;
const rowsOf = (refId) => {
  const frame = (context.panelData?.series ?? []).find((f) => f.refId === refId);
  if (!frame) {
    return [];
  }
  const n = frame.length ?? frame.fields[0]?.values.length ?? 0;
  return Array.from({ length: n }, (_, i) =>
    Object.fromEntries(frame.fields.map((f) => [f.name, f.values[i] ?? f.values.get?.(i)])),
  );
};

// Stations and hops, with the lines that serve each. The Green branches are one
// line here, as on the MBTA map.
const stations = new Map();
const hops = new Map();
const patterns = new Map();
// While a query runs again, the panel can be handed a frame without its rows'
// fields: only whole rows count.
const whole = (r) => r.pattern && r.station && COLOURS[r.line] && Number.isFinite(r.latitude) && Number.isFinite(r.longitude);
for (const r of rowsOf('N').filter(whole)) {
  if (!patterns.has(r.pattern)) {
    patterns.set(r.pattern, []);
  }
  patterns.get(r.pattern).push(r);
}
for (const rows of patterns.values()) {
  rows.sort((a, b) => a.seq - b.seq);
  rows.forEach((r, i) => {
    const s = stations.get(r.station) ?? { id: r.station, name: r.name, lat: r.latitude, lng: r.longitude, lines: new Set() };
    s.lines.add(r.line);
    stations.set(r.station, s);
    if (i > 0) {
      const [a, b] = [rows[i - 1].station, r.station].sort();
      const key = `${a}--${b}`;
      const hop = hops.get(key) ?? { a, b, lines: new Set() };
      hop.lines.add(r.line);
      hops.set(key, hop);
    }
  });
}
if (hops.size === 0) {
  // Keep the drawing there is; a network that never came says so.
  if (!self.svg) {
    box.textContent = 'The network did not load.';
  } else if (self.svg.parentNode !== box) {
    box.replaceChildren(self.svg);
  }
  return;
}

const quote = (s) => `"${String(s).replace(/["\\]/g, '\\$&')}"`;
const ORDER = ['Red', 'Mattapan', 'Orange', 'Green', 'Blue'];
const linesOf = (set) => ORDER.filter((l) => set.has(l));
// Positions in inches from the stations' coordinates, east-west shrunk by the
// cosine of Boston's latitude, as the start of the layout.
const dot = [
  'graph subway {',
  `  layout=neato; mode=KK; epsilon=0.0001; overlap=false; splines=false; outputorder=edgesfirst; bgcolor="transparent"; pad=0.3;`,
  `  node [shape=circle fixedsize=true width=0.13 label="" style=filled fillcolor=${quote(BACK)} penwidth=2 fontname="Inter, Helvetica, Arial, sans-serif" fontsize=9 fontcolor=${quote(TEXT)}];`,
  '  edge [penwidth=5 len=0.45];',
];
const byId = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
for (const id of [...stations.keys()].sort(byId)) {
  const s = stations.get(id);
  const x = (s.lng + 71.06) * 0.74 * 60;
  const y = (s.lat - 42.36) * 60;
  const lines = linesOf(s.lines);
  const transfer = lines.length > 1;
  dot.push(
    `  ${quote(s.id)} [id=${quote('n-' + s.id)} xlabel=${quote(s.name)} pos="${x.toFixed(3)},${y.toFixed(3)}" ` +
      `color=${quote(transfer ? TEXT : COLOURS[lines[0]])}${transfer ? ' width=0.19' : ''}];`,
  );
}
for (const key of [...hops.keys()].sort(byId)) {
  const h = hops.get(key);
  const lines = linesOf(h.lines);
  dot.push(
    `  ${quote(h.a)} -- ${quote(h.b)} [id=${quote(`e-${h.a}--${h.b}`)} color=${quote(lines.map((l) => COLOURS[l]).join(':'))}` +
      `${lines.length === 1 && lines[0] === 'Mattapan' ? ' penwidth=3' : ''}];`,
  );
}
dot.push('}');
// The same network always gives the same source, whatever order the rows come
// in, so the layout is computed once.
const source = dot.join('\n');

// What this render shows, kept on the panel: a layout still on its way draws
// the latest trains when it lands, and a frame handed over half-loaded keeps
// the trains of the one before.
const frameT = (context.panelData?.series ?? []).find((f) => f.refId === 'T');
const trains = frameT?.fields.some((f) => f.name === 'vehicle')
  ? rowsOf('T').filter((t) => t.vehicle && COLOURS[t.line] && t.to_station)
  : self.now?.trains ?? [];
const picked = { train: trains.find((t) => t.picked)?.vehicle ?? '', station: context.grafana.replaceVariables('${station}') };
self.now = { trains, picked, box, note };

const setVars = (vars) => context.grafana.locationService.partial(vars, true);

// Wheel zoom, drag to pan, double-click to fit, and clicks that pick a train or
// a station. Wired once per drawing.
const wire = (svg) => {
  const base = svg.viewBox.baseVal;
  const fit = [base.x, base.y, base.width, base.height];
  self.view = self.view ?? fit.slice();
  const apply = () => svg.setAttribute('viewBox', self.view.join(' '));
  apply();
  const toSvg = (ev) => {
    const r = svg.getBoundingClientRect();
    const [x, y, w, h] = self.view;
    // preserveAspectRatio xMidYMid meet: the scale is the smaller of the two.
    const k = Math.max(w / r.width, h / r.height);
    return [x + w / 2 + (ev.clientX - r.left - r.width / 2) * k, y + h / 2 + (ev.clientY - r.top - r.height / 2) * k, k];
  };
  svg.addEventListener(
    'wheel',
    (ev) => {
      ev.preventDefault();
      const [px, py] = toSvg(ev);
      const f = Math.exp(ev.deltaY * 0.0015);
      const [x, y, w, h] = self.view;
      const nw = Math.min(fit[2] * 1.5, Math.max(fit[2] / 12, w * f));
      const s = nw / w;
      self.view = [px - (px - x) * s, py - (py - y) * s, w * s, h * s];
      apply();
    },
    { passive: false },
  );
  let drag = null;
  svg.addEventListener('pointerdown', (ev) => {
    drag = { x: ev.clientX, y: ev.clientY, view: self.view.slice(), moved: false };
  });
  svg.addEventListener('pointermove', (ev) => {
    if (!drag) {
      return;
    }
    const dx = ev.clientX - drag.x;
    const dy = ev.clientY - drag.y;
    if (!drag.moved && Math.hypot(dx, dy) < 4) {
      return;
    }
    if (!drag.moved) {
      drag.moved = true;
      svg.setPointerCapture(ev.pointerId);
      svg.style.cursor = 'grabbing';
    }
    const [, , k] = toSvg(ev);
    self.view = [drag.view[0] - dx * k, drag.view[1] - dy * k, drag.view[2], drag.view[3]];
    apply();
  });
  const end = (ev) => {
    if (drag?.moved) {
      svg.releasePointerCapture?.(ev.pointerId);
    }
    svg.style.cursor = '';
    setTimeout(() => (drag = null), 0);
  };
  svg.addEventListener('pointerup', end);
  svg.addEventListener('pointercancel', end);
  svg.addEventListener('dblclick', (ev) => {
    ev.preventDefault();
    self.view = fit.slice();
    apply();
  });
  svg.addEventListener('click', (ev) => {
    if (drag?.moved) {
      return;
    }
    const train = ev.target.closest('[data-vehicle]');
    if (train) {
      setVars({ 'var-train': train.dataset.vehicle, 'var-station': '' });
      return;
    }
    const node = ev.target.closest('[data-station]');
    if (node) {
      const s = self.stations.get(node.dataset.station);
      setVars({ 'var-station': s.id, 'var-train': '', 'var-lat': s.lat.toFixed(6), 'var-lng': s.lng.toFixed(6) });
    }
  });
};

// The drawing: Graphviz's SVG, without its own titles (they show node ids),
// with a title per station and a layer for the trains.
const draw = (viz) => {
  const svg = viz.renderSVGElement(self.layoutSource);
  svg.removeAttribute('width');
  svg.removeAttribute('height');
  svg.classList.add('subway-svg');
  svg.querySelectorAll('title').forEach((t) => t.remove());
  for (const s of stations.values()) {
    const g = svg.getElementById('n-' + s.id);
    if (!g) {
      continue;
    }
    g.dataset.station = s.id;
    const title = document.createElementNS('http://www.w3.org/2000/svg', 'title');
    title.textContent = `${s.name} · ${linesOf(s.lines).join(', ')}`;
    g.append(title);
  }
  const layer = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  layer.classList.add('trains');
  svg.querySelector('g.graph').append(layer);
  self.trainEls = new Map();
  wire(svg);
  return svg;
};

// Where a train goes: on the drawn hop, at its share of the hop's length, set
// off to the right of its direction of travel so trains running opposite ways
// pass side by side.
const centre = (svg, id) => {
  const e = svg.getElementById('n-' + id)?.querySelector('ellipse');
  return e ? [e.cx.baseVal.value, e.cy.baseVal.value] : null;
};
const place = (svg, t) => {
  const colour = COLOURS[t.line].toLowerCase();
  if (t.from_station === t.to_station) {
    return centre(svg, t.to_station);
  }
  const [a, b] = [t.from_station, t.to_station].sort();
  const edge = svg.getElementById(`e-${a}--${b}`);
  if (!edge) {
    return centre(svg, t.to_station);
  }
  const paths = [...edge.querySelectorAll('path')];
  const path = paths.find((p) => (p.getAttribute('stroke') ?? '').toLowerCase() === colour) ?? paths[0];
  const len = path.getTotalLength();
  const start = path.getPointAtLength(0);
  const from = centre(svg, t.from_station);
  const to = centre(svg, t.to_station);
  // A path runs from its tail to its head; which end is which is read off the drawing.
  const forward = !from || !to || Math.hypot(start.x - from[0], start.y - from[1]) <= Math.hypot(start.x - to[0], start.y - to[1]);
  const s = (forward ? t.progress : 1 - t.progress) * len;
  const p = path.getPointAtLength(s);
  const q = path.getPointAtLength(Math.min(len, s + 1));
  const r = path.getPointAtLength(Math.max(0, s - 1));
  let dx = q.x - r.x;
  let dy = q.y - r.y;
  const d = Math.hypot(dx, dy) || 1;
  dx /= d;
  dy /= d;
  if (!forward) {
    dx = -dx;
    dy = -dy;
  }
  return [p.x - dy * 4.5, p.y + dx * 4.5];
};

const drawTrains = (svg) => {
  const { trains, picked, note } = self.now;
  const layer = svg.querySelector('g.trains');
  const seen = new Set();
  let placed = 0;
  for (const t of trains) {
    const at = place(svg, t);
    if (!at) {
      continue;
    }
    placed += 1;
    seen.add(t.vehicle);
    let g = self.trainEls.get(t.vehicle);
    if (!g) {
      g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.classList.add('train');
      g.dataset.vehicle = t.vehicle;
      g.innerHTML = '<circle class="ring" r="10"></circle><circle class="dot" r="4.2"></circle><title></title>';
      g.style.transform = `translate(${at[0]}px, ${at[1]}px)`;
      layer.append(g);
      self.trainEls.set(t.vehicle, g);
    }
    g.querySelector('.dot').setAttribute('fill', COLOURS[t.line]);
    g.querySelector('.dot').setAttribute('stroke', BACK);
    g.querySelector('.ring').setAttribute('stroke', PICK);
    g.classList.toggle('picked', t.vehicle === picked.train);
    const station = self.stations.get(t.station)?.name ?? t.station;
    g.querySelector('title').textContent =
      `${t.route.replace('-', ' ')} · train ${t.unit}${t.toward ? ' to ' + t.toward : ''}\n${t.status} ${station}`;
    // Next frame, so a new train appears in place and a known one glides.
    requestAnimationFrame(() => (g.style.transform = `translate(${at[0]}px, ${at[1]}px)`));
  }
  for (const [vehicle, g] of self.trainEls) {
    if (!seen.has(vehicle)) {
      g.remove();
      self.trainEls.delete(vehicle);
    }
  }
  // The picked train on top.
  const top = self.trainEls.get(picked.train);
  if (top) {
    layer.append(top);
  }
  svg.querySelectorAll('g.node.picked').forEach((g) => g.classList.remove('picked'));
  svg.getElementById('n-' + picked.station)?.classList.add('picked');
  if (note) {
    const lost = trains.length - placed;
    note.textContent =
      `${placed} trains on the diagram${lost ? `, ${lost} not placed` : ''} · ` +
      `laid out by Graphviz (neato, ${self.layoutSource.includes('mode=KK') ? 'Kamada-Kawai' : 'stress majorization'}) in your browser · ` +
      'wheel to zoom, drag to pan, double-click to fit';
  }
};

self.stations = stations;
if (self.source !== source) {
  self.source = source;
  self.svg = null;
  self.view = null;
  box.textContent = 'Laying out the network with Graphviz…';
  const load = () =>
    import(VIZ)
      .then((m) => m.instance())
      .catch((err) => {
        self.viz = null;
        throw err;
      });
  const show = (viz, layoutSource) => {
    self.layoutSource = layoutSource;
    self.svg = draw(viz);
    self.now.box.replaceChildren(self.svg);
    drawTrains(self.svg);
  };
  self.viz = self.viz ?? load();
  self.viz
    .then((viz) => {
      if (self.source !== source) {
        return;
      }
      try {
        show(viz, source);
      } catch (err) {
        // Graphviz compiled to WebAssembly aborts on some inputs, and an aborted
        // instance is unusable: a new one, with neato's default stress
        // majorization instead of Kamada-Kawai.
        self.viz = load();
        return self.viz.then((fresh) => show(fresh, source.replace('mode=KK; ', '')));
      }
    })
    .catch((err) => {
      // Tried again on the next render.
      self.source = null;
      self.now.box.textContent = `Graphviz did not draw the network: ${err.message ?? err}`;
    });
} else if (self.svg) {
  if (self.svg.parentNode !== box) {
    box.replaceChildren(self.svg);
  }
  drawTrains(self.svg);
}
// Otherwise the layout of this network is on its way, and draws these trains.

options.styles:
.subway { display: flex; flex-direction: column; height: 100%; }
.subway-map { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; color: #9AA5B1; }
.subway-svg { width: 100%; height: 100%; display: block; cursor: grab; user-select: none; touch-action: none; }
.subway-svg .node { cursor: pointer; }
.subway-svg .node.picked ellipse { fill: #FFE14D; stroke: #FFE14D; stroke-width: 5; }
.subway-svg .node.picked text { font-weight: 700; }
.subway-svg .train { cursor: pointer; transition: transform 2.5s ease-in-out; }
.subway-svg .train .dot { stroke-width: 1.5; }
.subway-svg .train .ring { fill: none; stroke-width: 2.5; display: none; }
.subway-svg .train.picked .ring { display: inline; animation: subway-pulse 1.6s ease-out infinite; }
@keyframes subway-pulse { from { r: 5px; opacity: 1; } to { r: 15px; opacity: 0; } }
.subway-note { font-size: 11px; line-height: 1.4; color: #9AA5B1; padding: 2px 4px 0; }

.board { font-size: 14px; line-height: 1.3; }
.board-head { font-weight: 600; font-size: 16px; margin-bottom: 6px; }
.board-row { display: flex; align-items: center; gap: 10px; padding: 4px 0; border-bottom: 1px solid rgba(128, 128, 128, 0.2); }
.badge { min-width: 64px; text-align: center; border-radius: 3px; color: #fff; font-weight: 600; font-size: 12px; padding: 2px 6px; }
.to { flex: 1; }
.due { font-variant-numeric: tabular-nums; font-weight: 600; }
